var HUDPROMPTZ=0.6;
// v16.xx (feedocc2), HIS NOTE (2026-10-14): "can you make it so text (like the press e to loot text) can be blocked by player or enemy
// sprites?". A PROMPT IS COVERED BY THE BODIES IN FRONT OF ITS OBJECT. The world text is drawn on the HUD canvas, over the world, so a body
// could never stand over it. Each prompt now knows its depth (the ground y of its object, found from its anchor: the prompts hang 26 above
// it) and, before it draws, takes out of its own clip the silhouette of every body that sorts in front of that depth (a bigger y, as the
// bodies sort): the player, a teammate, a pillager, a machine. The body that is in the world pass shows through the hole, so it reads as
// standing over the text, at its own size, from the same feet and height the sprites are drawn from. A body behind the object, and
// the object's own body, cover nothing. Several bodies are several clips, so they take out their union. Drawing only; the prompts
// that nothing stands in front of draw exactly as they did.
var OCCHW={sentry:0.95,crawler:0.9,snitch:0.9,choir:0.9,warden:0.9,howler:0.9,bulwark:0.9,listener:0.9};
function occBodies(){
  var out=[], p=G&&G.player, i, e, g;
  if(!G||G.sim) return out;
  if(p&&!p.specOut&&!p.dead) out.push({x:p.x,y:p.y,r:Math.max(8,p.r||11),h:p.downed?16:42,kind:'raider',src:p});
  for(i=0;G.ents&&i<G.ents.length;i++){
    e=G.ents[i]; if(!e||!e.seen||!(e.x===e.x)) continue;
    if(e.kind==='listener'&&e.state==='dormant') continue;
    out.push({x:e.x,y:e.y,r:Math.max(6,e.r||10),h:(e.downed||e.state==='down'||e.state==='possum')?14:spriteTop(e)+2,kind:e.kind,src:e});
  }
  if(typeof NET==='object'&&NET&&NET.on&&NET.up) for(i=0;i<NET.up.length;i++){ g=NET.up[i]; if(g&&netUpShown(g)) out.push({x:g.x,y:g.y,r:11,h:g.dn?16:42,kind:'raider',src:g}); }
  return out;
}
// rect: screen CSS pixels; wy: the world depth of the thing the text belongs to; self: a body that never covers it. Returns the number of clips made.
function occClipScr(rect,wy,self){
  var L=occBodies(), q=ZOOM(), n=0, i, b, s, hw, top, m;
  if(!L.length) return 0;
  m=ctx.getTransform();
  for(i=0;i<L.length;i++){
    b=L[i]; if(b.src===self||!(b.y>wy+0.5)) continue;
    s=w2s(b.x,0,b.y); hw=b.r*(OCCHW[b.kind]||0.72)*q; top=s.y-b.h*q;
    if(s.x+hw<rect.x||s.x-hw>rect.x+rect.w||s.y+hw*0.45<rect.y||top>rect.y+rect.h) continue;
    if(!n) ctx.setTransform(DPRH,0,0,DPRH,0,0);
    ctx.beginPath(); ctx.rect(rect.x-2,rect.y-2,rect.w+4,rect.h+4);
    ctx.moveTo(s.x-hw,s.y); ctx.lineTo(s.x-hw,top+hw); ctx.arc(s.x,top+hw,hw,Math.PI,0,false); ctx.lineTo(s.x+hw,s.y); ctx.ellipse(s.x,s.y,hw,hw*0.45,0,0,Math.PI,false); ctx.closePath();
    ctx.clip('evenodd'); n++;
  }
  if(n) ctx.setTransform(m);
  return n;
}
// a prompt's plate in the local space of the caller (anchor ax, ay): its screen rect and depth, then the clips
function occClipPrompt(lx,ly,lw,lh,ax,ay){
  var m=ctx.getTransform(), k=1/((DPRH>0)?DPRH:1), x0=(m.a*lx+m.c*ly+m.e)*k, y0=(m.b*lx+m.d*ly+m.f)*k, x1=(m.a*(lx+lw)+m.c*(ly+lh)+m.e)*k, y1=(m.b*(lx+lw)+m.d*(ly+lh)+m.f)*k, sy=(m.b*ax+m.d*ay+m.f)*k, wy;
  if(!G||!G.player||G.sim||typeof VY==='undefined') return 0;
  wy=(sy+26)/ZOOM()+VY;
  return occClipScr({x:Math.min(x0,x1),y:Math.min(y0,y1),w:Math.abs(x1-x0),h:Math.abs(y1-y0)},wy,null);
}

