{v:'VER',what:'his note: a body in front of a prompt covers it: the player standing below a prompt hides the part of it behind his sprite, and the part clear of him stays',
 run:function(){
   if(!window.__deploy||!window.__endRaid||!window.__frame||typeof hudPrompt!=='function') return 'SKIP: no raid or prompts here';
   if(typeof occClipScr!=='function') return 'prompts are not covered by the bodies in front of them in this build';
   var bad=[], g, p, s, r, q, i, chest, edge, far;
   function alphaAt(x,y){ var k=(typeof DPRH==='number'&&DPRH>0)?DPRH:1, im=ctx.getImageData(Math.round(x*k),Math.round(y*k),1,1).data; return im[3]; }
   try{
     __topClear(); __runPrep(); __resetCfg(); __pinDefaults(0); __cleanProfile();
     try{ __pinDPR(1); }catch(_d){}
     __deploy({kit:[],safe:null,mapIx:0,seed:4242});
     g=__state(); if(!g||!g.player||g.over) return 'SKIP: no live raid';
     g.bagOpen=false; g.mapOpen=false; g.ents.length=0; keys={}; p=g.player; p.iv=99;
     for(i=0;i<4;i++) __frame(0.016);
     q=ZOOM();
     // a crate 8 units behind the player (above him on the screen): he stands in front of its prompt
     s=w2s(p.x,26,p.y-8);
     ctx.clearRect(0,0,W,H);
     r=hudPrompt('[E] SEARCH CRATE TEST',s.x,s.y,{});
     chest=alphaAt(s.x,s.y); edge=alphaAt(s.x-r.w/2-2,s.y-2); far=alphaAt(s.x+r.w/2+2,s.y-2);
     if(chest!==0) bad.push('the prompt is drawn over the body standing in front of it (alpha '+chest+' at his chest)');
     if(!(edge>0&&far>0)) bad.push('the part of the prompt clear of the body is gone (alpha '+edge+' and '+far+')');
     // a crate 40 units in front of him (below him on the screen): he is behind it and covers nothing
     ctx.clearRect(0,0,W,H);
     s=w2s(p.x,26,p.y+40);
     r=hudPrompt('[E] SEARCH CRATE TEST',s.x,s.y,{});
     if(!(alphaAt(s.x,s.y)>0)) bad.push('a body behind the object covers its prompt');
     ctx.clearRect(0,0,W,H);
   }catch(e){ bad.push('threw: '+(e&&e.message||e)); }
   finally{ try{ ctx.clearRect(0,0,W,H); }catch(_c){} try{ var g2=__state(); if(g2&&!g2.over){ g2.player.iv=0; g2.player.downed=false; __endRaid('abandon'); } }catch(_e){} __topClear(); __cleanProfile(); }
   return bad.length?bad.join('; '):null; }},
